class OrderListFragment : Fragment(R.layout.fragment_order_list) {

    private val viewModel: OrderListViewModel by viewModels()

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        val binding = FragmentOrderListBinding.bind(view)

        // viewLifecycleOwner, not `this`: a fragment on the back stack outlives
        // its view, and collecting against the fragment leaks the binding.
        viewLifecycleOwner.lifecycleScope.launch {
            // Without repeatOnLifecycle this keeps collecting in the background.
            // That is the drain users report as "the app eats my battery".
            viewLifecycleOwner.repeatOnLifecycle(Lifecycle.State.STARTED) {
                viewModel.state.collect { state ->
                    when (state) {
                        is OrderListState.Loading ->
                            binding.progress.isVisible = true
                        is OrderListState.Loaded -> {
                            binding.progress.isVisible = false
                            adapter.submitList(state.orders)
                        }
                        is OrderListState.Failed -> {
                            binding.progress.isVisible = false
                            binding.error.text = state.message
                        }
                    }
                }
            }
        }
    }
}
